import os
import json

d = os.environ['RLM_SESSION_DIR']
sess = os.path.basename(d)

with open(d+'/../../sessions/'+sess+'.jsonl', 'r') as f:
    lines = f.readlines()

print(f"Total lines: {len(lines)}")

# Check first 20 messages
for i, line in enumerate(lines[:30]):
    msg = json.loads(line)
    role = msg.get('role', 'unknown')
    if role == 'assistant':
        for content_item in msg.get('content', []):
            if isinstance(content_item, dict):
                if content_item.get('type') == 'text':
                    text = content_item.get('text', '')
                    if 'Demo' in text or 'input' in text.lower():
                        print(f"Line {i}: Assistant message with demo")
                        # Extract simpler pattern for grids
                        # Find consecutive lines of space-separated digits
                        parts = text.split('\n')
                        in_grid = False
                        grid_rows = []
                        for part in parts:
                            if part.strip() and part.strip().isdigit() and len(part) < 200:
                                if part[0].isdigit():
                                    in_grid = True
                                    grid_rows.append(part)
                            elif in_grid and not part.strip():
                                break
                        if grid_rows:
                            print(f"  First {len(grid_rows)} rows:\n" + "\n".join(grid_rows[:5]))
